// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(address to, uint256 tokenId, uint256 amount) public {
        vm.assume(to != address(0));
        vm.assume(amount > 0);
        vm.startPrank(address(this));
        c.adjustAdminAccess(address(this), true);
        c.createGameItem("item", "", false, true, 0, 0, 0);
        vm.stopPrank();
        vm.assume(to != address(0));
        uint256 balance = c.balanceOf(to, tokenId);
        assertTrue(balance == 0);
    }
}
